@code {
    private List<ShipmentDto>? shipments;
    private bool loading = true;
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;

    private IEnumerable<ShipmentDto> FilteredShipments => (shipments ?? [])
        .Where(s => string.IsNullOrEmpty(filterText) ||
                     s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                     s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                     s.RecipientName.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        .Where(s => string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter);

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch
        {
            shipments = null;
        }
        loading = false;
    }

    private async Task UpdateStatus(int shipmentId, string newStatus)
    {
        await ShipmentService.UpdateShipmentStatusAsync(new ShipmentStatusUpdate
        {
            ShipmentId = shipmentId,
            NewStatus = newStatus
        });
        await LoadShipments();
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Pending" => "bg-secondary",
        "Delayed" => "bg-warning text-dark",
        _ => "bg-info"
    };
}
