using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Pages;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Components;
using ShipmentTracker.Components.Account;
using ShipmentTracker.Data;
using ShipmentTracker.Services;

builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();

builder.Services.AddScoped<IShipmentService, ServerShipmentService>();

var app = builder.Build();

// Seed sample data
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    db.Database.Migrate();

    if (!db.Shipments.Any())
    {
        db.Shipments.AddRange(
            new Shipment { TrackingNumber = "TRK-001-2026", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = "In Transit", ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), RecipientName = "Alice Johnson", CarrierName = "FastFreight", WeightKg = 12.5 },
            new Shipment { TrackingNumber = "TRK-002-2026", Origin = "Chicago, IL", Destination = "Miami, FL", Status = "Pending", ShippedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(4), RecipientName = "Bob Smith", CarrierName = "SpeedLogistics", WeightKg = 8.2 },
            new Shipment { TrackingNumber = "TRK-003-2026", Origin = "Seattle, WA", Destination = "Denver, CO", Status = "Delivered", ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), ActualDelivery = DateTime.UtcNow.AddDays(-2), RecipientName = "Carol Davis", CarrierName = "FastFreight", WeightKg = 3.1 },
            new Shipment { TrackingNumber = "TRK-004-2026", Origin = "Houston, TX", Destination = "Phoenix, AZ", Status = "In Transit", ShippedDate = DateTime.UtcNow.AddDays(-2), EstimatedDelivery = DateTime.UtcNow.AddDays(1), RecipientName = "David Lee", CarrierName = "GlobalShip", WeightKg = 25.0 },
            new Shipment { TrackingNumber = "TRK-005-2026", Origin = "Boston, MA", Destination = "Atlanta, GA", Status = "Delayed", ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(3), RecipientName = "Eva Martinez", CarrierName = "SpeedLogistics", WeightKg = 6.7 }
        );
        db.SaveChanges();
    }
}

app.MapAdditionalIdentityEndpoints();

// Shipment API endpoints
var shipments = app.MapGroup("api/shipments");

shipments.MapGet("/", async (IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()))
    .RequireAuthorization();

shipments.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
});

shipments.MapPost("/update-status", async (ShipmentStatusUpdate update, IShipmentService service) =>
{
    await service.UpdateShipmentStatusAsync(update);
    return Results.Ok();
}).RequireAuthorization();

app.Run();

