﻿@page "/"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>ShipmentTracker - Track Your Shipments</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">📦 Shipment Tracker</h1>
    <p class="lead text-muted">Track your shipments in real time</p>
</div>

<div class="row justify-content-center">
    <div class="col-md-8 col-lg-6">
        <div class="card shadow-sm">
            <div class="card-body p-4">
                <h5 class="card-title mb-3">Track a Shipment</h5>
                <div class="input-group">
                    <input type="text" class="form-control form-control-lg"
                           placeholder="Enter tracking number (e.g. TRK-001-2026)"
                           @bind="trackingNumber" @bind:event="oninput"
                           @onkeydown="HandleKeyDown" />
                    <button class="btn btn-primary btn-lg" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                        Track
                    </button>
                </div>

                @if (searched && shipment is null)
                {
                    <div class="alert alert-warning mt-3 mb-0">
                        <strong>Not found.</strong> No shipment matches tracking number "<strong>@searchedNumber</strong>".
                    </div>
                }

                @if (shipment is not null)
                {
                    <div class="card mt-3 border-success">
                        <div class="card-header bg-success text-white">
                            Shipment @shipment.TrackingNumber
                        </div>
                        <div class="card-body">
                            <dl class="row mb-0">
                                <dt class="col-sm-5">Status</dt>
                                <dd class="col-sm-7"><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></dd>
                                <dt class="col-sm-5">Origin</dt>
                                <dd class="col-sm-7">@shipment.Origin</dd>
                                <dt class="col-sm-5">Destination</dt>
                                <dd class="col-sm-7">@shipment.Destination</dd>
                                <dt class="col-sm-5">Recipient</dt>
                                <dd class="col-sm-7">@shipment.RecipientName</dd>
                                <dt class="col-sm-5">Carrier</dt>
                                <dd class="col-sm-7">@shipment.CarrierName</dd>
                                <dt class="col-sm-5">Shipped</dt>
                                <dd class="col-sm-7">@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>
                                <dt class="col-sm-5">Est. Delivery</dt>
                                <dd class="col-sm-7">@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</dd>
                                @if (shipment.ActualDelivery.HasValue)
                                {
                                    <dt class="col-sm-5">Delivered</dt>
                                    <dd class="col-sm-7">@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</dd>
                                }
                                <dt class="col-sm-5">Weight</dt>
                                <dd class="col-sm-7">@shipment.WeightKg.ToString("F1") kg</dd>
                            </dl>
                        </div>
                    </div>
                }
            </div>
        </div>
    </div>
</div>

<div class="row justify-content-center mt-4">
    <div class="col-md-8 col-lg-6 text-center">
        <AuthorizeView>
            <Authorized>
                <a href="dashboard" class="btn btn-outline-primary">
                    Go to Dispatcher Dashboard →
                </a>
            </Authorized>
            <NotAuthorized>
                <p class="text-muted">
                    <a href="Account/Login">Log in</a> to access the dispatcher dashboard.
                </p>
            </NotAuthorized>
        </AuthorizeView>
    </div>
</div>

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool searched;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        searched = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Pending" => "bg-secondary",
        "Delayed" => "bg-warning text-dark",
        _ => "bg-info"
    };
}

