 @page "/dashboard"
 @using Microsoft.AspNetCore.Authorization
 @using ShipmentTracker.Client.Models
 @using ShipmentTracker.Client.Services
 @attribute [Authorize]
 @inject IShipmentService ShipmentService

 <PageTitle>Dispatcher Dashboard</PageTitle>

 <h2 class="mb-4">📋 Dispatcher Dashboard</h2>

 <div class="row mb-3">
     <div class="col-md-4">
         <input type="text" class="form-control" placeholder="Filter by destination..."
                @bind="filterText" @bind:event="oninput" />
     </div>
     <div class="col-md-3">
         <select class="form-select" @bind="statusFilter">
             <option value="">All Statuses</option>
             <option value="Pending">Pending</option>
             <option value="In Transit">In Transit</option>
             <option value="Delivered">Delivered</option>
             <option value="Delayed">Delayed</option>
         </select>
     </div>
     <div class="col-md-3">
         <button class="btn btn-outline-secondary" @onclick="LoadShipments">
             🔄 Refresh
         </button>
     </div>
 </div>

 @if (loading)
 {
     <p><em>Loading shipments...</em></p>
 }
 else if (shipments is null)
 {
     <div class="alert alert-danger">Failed to load shipments.</div>
 }
 else
 {
     <div class="table-responsive">
         <table class="table table-striped table-hover">
             <thead class="table-dark">
                 <tr>
                     <th>Tracking #</th>
                     <th>Origin</th>
                     <th>Destination</th>
                     <th>Recipient</th>
                     <th>Carrier</th>
                     <th>Weight</th>
                     <th>Shipped</th>
                     <th>Est. Delivery</th>
                     <th>Status</th>
                     <th>Actions</th>
                 </tr>
             </thead>
             <tbody>
                 @foreach (var s in FilteredShipments)
                 {
                     <tr>
                         <td><strong>@s.TrackingNumber</strong></td>
                         <td>@s.Origin</td>
                         <td>@s.Destination</td>
                         <td>@s.RecipientName</td>
                         <td>@s.CarrierName</td>
                         <td>@s.WeightKg.ToString("F1") kg</td>
                         <td>@s.ShippedDate.ToString("MMM dd")</td>
                         <td>@s.EstimatedDelivery.ToString("MMM dd")</td>
                         <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                         <td>
                             @if (s.Status != "Delivered")
                             {
                                 <div class="dropdown">
                                     <button class="btn btn-sm btn-outline-primary dropdown-toggle" type="button"
                                             data-bs-toggle="dropdown">
                                         Update
                                     </button>
                                     <ul class="dropdown-menu">
                                         @foreach (var status in new[] { "Pending", "In Transit", "Delayed", "Delivered" })
                                         {
                                             @if (status != s.Status)
                                             {
                                                 <li>
                                                     <button class="dropdown-item" @onclick="() => UpdateStatus(s.Id, status)">
                                                         @status
                                                     </button>
                                                 </li>
                                             }
                                         }
                                     </ul>
                                 </div>
                             }
                             else
                             {
                                 <span class="text-muted">—</span>
                             }
                         </td>
                     </tr>
                 }
             </tbody>
         </table>
     </div>

     <div class="row mt-3">
         <div class="col">
             <span class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</span>
         </div>
     </div>
 }

 @code {
     private List<ShipmentDto>? shipments;
     private bool loading = true;
     private string filterText = string.Empty;
     private string statusFilter = string.Empty;

     private IEnumerable<ShipmentDto> FilteredShipments => (shipments ?? [])
         .Where(s => string.IsNullOrEmpty(filterText) ||
                      s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                      s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                      s.RecipientName.Contains(filterText, StringComparison.OrdinalIgnoreCase))
         .Where(s => string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter);

     protected override async Task OnInitializedAsync()
     {
         await LoadShipments();
     }

     private async Task LoadShipments()
     {
         loading = true;
         try
         {
             shipments = await ShipmentService.GetAllShipmentsAsync();
         }
         catch
         {
             shipments = null;
         }
         loading = false;
     }

     private async Task UpdateStatus(int shipmentId, string newStatus)
     {
         await ShipmentService.UpdateShipmentStatusAsync(new ShipmentStatusUpdate
         {
             ShipmentId = shipmentId,
             NewStatus = newStatus
         });
         await LoadShipments();
     }

     private static string GetStatusBadgeClass(string status) => status switch
     {
         "Delivered" => "bg-success",
         "In Transit" => "bg-primary",
         "Pending" => "bg-secondary",
         "Delayed" => "bg-warning text-dark",
         _ => "bg-info"
     };
 }

